/**
 * The Friends
 * -----------
 * Eliphaz, Bildad and Zophar argue: the righteous prosper, the wicked fall — therefore repent, Job. Stage: a desert camp at dawn, three men in flowing robes, a fourth in ashes, the argument turning from comfort to accusation; wind, dust, long shadows.
 *
 * Palette 0x1a2a14 → 0x060402 · light: ember · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./job-kit.js.
 */

import { THREE, createScene, tent, firepit, pillar, person } from './job-kit.js';

const BG = 0x1a2a14;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 1617477407, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents, smoke rising */
    tent(W, group, -2.0, 0, -5.5, 1.00, 0xc8b088, W.r() * 6);
    tent(W, group, 17.2, 0, -21.9, 1.07, 0x8a6a44, W.r() * 6);
    tent(W, group, -6.3, 0, -3.0, 1.02, 0xa8704a, W.r() * 6);
    firepit(W, group, 6.2, 0, 3.0, 1.0);

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x22371a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x1a2a14, bend: 0.55, armR: [-0.4, 0.2], armL: [-0.3, -0.2], ry: 0.20, s: 1.18 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, bend: 0.55, armR: [-0.4, 0.2], armL: [-0.3, -0.2], ry: 0.08, s: 1.14 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, bend: 0.55, armR: [-0.4, 0.2], armL: [-0.3, -0.2], ry: -0.62, s: 1.07 });

    return W.finish();
}

export default { build };
